{
  "headline": "{{level.name}} वायु गुणवत्ता में घर के अंदर साफ़ हवा और फ़िट N95 पर ध्यान दें",
  "summary": "वर्तमान US AQI {{aqi.now}} के साथ आज का स्तर {{level.name}} है। सुरक्षा कदमों से सांस का संपर्क {{exposure.before}} से {{exposure.after}} हो सकता है, और सबसे साफ़ समय {{best.start}} से {{best.end}} है।",
  "cards": [
    {
      "actionId": "cooking_ventilation",
      "title": "खाना बनाते समय वेंटिलेशन का उपयोग करें",
      "why": "खाना पकाने से निकलने वाले धुएं को बाहर निकालने से घर के अंदर की हवा की गुणवत्ता में सुधार होता है, जिससे PM2.5 का स्तर {{impact.cooking_ventilation.ugm3}} तक कम हो सकता है।",
      "when": "जब भी आप खाना पका रहे हों।",
      "steps": [
        "खाना पकाते समय एग्जॉस्ट फैन या खिड़की खोलें।",
        "खाना पकाने के बाद कुछ देर तक वेंटिलेशन जारी रखें।"
      ]
    },
    {
      "actionId": "damp_mop_dont_sweep",
      "title": "धूल झाड़ने के बजाय नम पोंछा लगाएँ",
      "why": "धूल झाड़ने से हवा में धूल के कण फैलते हैं, जबकि नम पोंछा लगाने से वे नीचे बैठ जाते हैं, जिससे हवा की गुणवत्ता {{impact.damp_mop_dont_sweep.pct}} तक बेहतर होती है।",
      "when": "नियमित रूप से घर की सफाई करते समय।",
      "steps": [
        "पोंछे के लिए गीले कपड़े का प्रयोग करें।",
        "सूखे झाड़ू का प्रयोग करने से बचें।"
      ]
    },
    {
      "actionId": "errands_in_best_window",
      "title": "बाहरी काम सबसे अच्छे समय पर करें",
      "why": "बाहरी काम {{best.start}} से {{best.end}} के बीच करें जब हवा की गुणवत्ता सबसे अच्छी होती है, जिससे आपका संपर्क कम हो जाता है।",
      "when": "जब हवा की गुणवत्ता {{level.name}} हो।",
      "steps": [
        "अपने दैनिक कामों की योजना इस समय के अनुसार बनाएँ।",
        "बाहरी गतिविधियों को इस अवधि तक सीमित रखें।"
      ]
    },
    {
      "actionId": "no_idling",
      "title": "गाड़ी को बेवजह चालू न छोड़ें",
      "why": "गाड़ी को चालू छोड़ने से {{co2e.no_idling}} उत्सर्जन होता है और स्थानीय वायु प्रदूषण बढ़ता है।",
      "when": "जब आप गाड़ी से बाहर हों और इंजन चालू हो।",
      "steps": [
        "जब आप गाड़ी से उतरें तो इंजन बंद कर दें।",
        "खासकर स्कूल या सार्वजनिक स्थानों पर इंतज़ार करते समय इंजन बंद रखें।"
      ]
    },
    {
      "actionId": "share_community_brief",
      "title": "सामुदायिक संक्षिप्त जानकारी साझा करें",
      "why": "सामुदायिक स्तर पर धूल और डीजल उत्सर्जन को कम करने के प्रयासों से सभी को लाभ होता है, जिससे हवा की गुणवत्ता {{impact.share_community_brief.pct}} तक सुधर सकती है।",
      "when": "अगली सामुदायिक बैठक से पहले।",
      "steps": [
        "एक संक्षिप्त जानकारी तैयार करें जिसमें धूल और डीजल उत्सर्जन को कम करने के उपाय हों।",
        "इसे अपने रेजिडेंट वेलफेयर एसोसिएशन (RWA) या स्थानीय समुदाय समूह के साथ साझा करें।"
      ]
    }
  ],
  "memberNotes": [
    {
      "group": "child",
      "note": "{{level.name}} स्तर पर बच्चों का खेल घर के अंदर रखें।"
    },
    {
      "group": "senior",
      "note": "बाहरी गतिविधियों को कम करें और घर के अंदर रहें।"
    },
    {
      "group": "respiratory",
      "note": "राहत दवा पास रखें और बाहर भारी मेहनत से बचें।"
    }
  ],
  "tradeoffs": [
    "नम पोंछा लगाने से धूल के कण हवा में कम फैलते हैं, जिससे हवा की गुणवत्ता {{impact.damp_mop_dont_sweep.pct}} तक बेहतर होती है।"
  ]
}
